<?php

declare(strict_types=1);
require_once __DIR__.'/../config/database.php';require_once __DIR__.'/../includes/auth.php';require_role('admin');
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['payment_id']??0);$action=$_POST['action']??'';$note=trim($_POST['admin_note']??'');$stmt=$pdo->prepare("SELECT p.*,b.id booking_id FROM payments p JOIN bookings b ON b.id=p.booking_id WHERE p.id=?");$stmt->execute([$id]);$payment=$stmt->fetch();if(!$payment){flash('danger','Pembayaran tidak ditemukan.');redirect('admin/payments.php');}try{$pdo->beginTransaction();if($action==='verify'){$stmt=$pdo->prepare("UPDATE payments SET verification_status='verified',admin_note=?,verified_by=?,verified_at=NOW() WHERE id=?");$stmt->execute([$note,current_user()['id'],$id]);$stmt=$pdo->prepare("UPDATE bookings SET status='confirmed' WHERE id=?");$stmt->execute([$payment['booking_id']]);$detail=$pdo->prepare("SELECT b.*,p.duration_hours,p.name package_name,u.name customer_name FROM bookings b JOIN packages p ON p.id=b.package_id JOIN users u ON u.id=b.user_id WHERE b.id=?");$detail->execute([$payment['booking_id']]);$b=$detail->fetch();$start=new DateTime($b['event_date'].' '.$b['start_time']);$end=(clone $start)->modify('+'.(float)$b['duration_hours'].' hours');$stmt=$pdo->prepare("INSERT INTO schedules(booking_id,event_date,start_time,end_time,notes,status) VALUES(?,?,?,?,?,'scheduled') ON DUPLICATE KEY UPDATE event_date=VALUES(event_date),start_time=VALUES(start_time),end_time=VALUES(end_time),notes=VALUES(notes),status='scheduled'");$stmt->execute([$b['id'],$b['event_date'],$b['start_time'],$end->format('H:i:s'),'Jadwal '.$b['package_name'].' - '.$b['customer_name']]);$msg='Pembayaran diverifikasi dan pesanan masuk jadwal.';}elseif($action==='reject'){$stmt=$pdo->prepare("UPDATE payments SET verification_status='rejected',admin_note=?,verified_by=?,verified_at=NOW() WHERE id=?");$stmt->execute([$note,current_user()['id'],$id]);$stmt=$pdo->prepare("UPDATE bookings SET status='awaiting_payment' WHERE id=?");$stmt->execute([$payment['booking_id']]);$msg='Pembayaran ditolak. Pelanggan dapat mengunggah bukti baru.';}else{throw new RuntimeException('Tindakan tidak valid.');}$pdo->commit();flash('success',$msg);}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash('danger','Proses gagal: '.$e->getMessage());}redirect('admin/payments.php');}
$status=trim($_GET['status']??'');$sql="SELECT py.*,b.booking_code,b.dp_amount,u.name customer_name,p.name package_name FROM payments py JOIN bookings b ON b.id=py.booking_id JOIN users u ON u.id=b.user_id JOIN packages p ON p.id=b.package_id";$params=[];if($status!==''){$sql.=" WHERE py.verification_status=?";$params[]=$status;}$sql.=" ORDER BY py.created_at DESC";$stmt=$pdo->prepare($sql);$stmt->execute($params);$rows=$stmt->fetchAll();
$pageTitle='Verifikasi Pembayaran';require __DIR__.'/../includes/header.php';require __DIR__.'/../includes/admin_nav.php';
?>
<section class="section" style="padding-top:30px"><div class="container"><div class="dashboard-head"><div><h1>Verifikasi Pembayaran</h1><p>Periksa bukti transfer sebelum mengonfirmasi jadwal.</p></div></div><div class="panel"><div class="panel-body"><form class="filter-bar" method="get"><div class="form-group"><label>Status</label><select name="status"><option value="">Semua status</option><?php foreach(['pending','verified','rejected'] as $s): ?><option value="<?= $s ?>" <?= $status===$s?'selected':'' ?>><?= e(payment_status_label($s)) ?></option><?php endforeach; ?></select></div><button class="btn btn-dark" type="submit">Terapkan</button><a class="btn btn-outline" href="<?= url('admin/payments.php') ?>">Reset</a></form></div></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Pesanan</th><th>Pelanggan</th><th>Pembayaran</th><th>Bukti</th><th>Status</th><th>Verifikasi</th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="6" class="empty">Data pembayaran tidak ditemukan.</td></tr><?php else: foreach($rows as $r): ?><tr><td><strong><?= e($r['booking_code']) ?></strong><br><small><?= e($r['package_name']) ?></small></td><td><?= e($r['customer_name']) ?></td><td><?= rupiah($r['amount']) ?><br><small><?= date('d-m-Y',strtotime($r['payment_date'])) ?> · <?= e($r['bank_name']) ?> / <?= e($r['account_name']) ?></small><br><small>DP: <?= rupiah($r['dp_amount']) ?></small></td><td><a class="btn btn-outline btn-sm" target="_blank" href="<?= url('uploads/payments/'.$r['proof']) ?>">Lihat Bukti</a></td><td><span class="badge badge-<?= status_class($r['verification_status']) ?>"><?= e(payment_status_label($r['verification_status'])) ?></span><?php if($r['admin_note']): ?><br><small><?= e($r['admin_note']) ?></small><?php endif; ?></td><td><?php if($r['verification_status']==='pending'): ?><form method="post"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="payment_id" value="<?= (int)$r['id'] ?>"><input name="admin_note" placeholder="Catatan (opsional)" style="min-width:180px;margin-bottom:6px"><div class="table-actions"><button class="btn btn-success btn-sm" name="action" value="verify" data-confirm="Verifikasi pembayaran ini?" type="submit">Terima</button><button class="btn btn-danger btn-sm" name="action" value="reject" data-confirm="Tolak pembayaran ini?" type="submit">Tolak</button></div></form><?php else: ?>Sudah diproses<?php endif; ?></td></tr><?php endforeach; endif; ?></tbody></table></div></div></div></section>
